"""
Convert CSV, JSON (list of objects), or pipe-delimited text into a Markdown table and an HTML table.
Detects headers, right-aligns numeric columns, reports field count mismatches.
"""

import json
import re

def _detect_format(text: str) -> str:
    """Detect the input format: csv, json, or pipe."""
    if not text.strip():
        raise ValueError("Input is empty")
    stripped = text.strip()
    if stripped.startswith('['):
        return 'json'
    # Check for pipe presence
    if '|' in stripped:
        # If there are also commas and no pipe header, might be csv with pipes in data - unlikely
        # Assume pipe if more pipes than commas
        pipe_count = stripped.count('|')
        comma_count = stripped.count(',')
        if pipe_count > comma_count:
            return 'pipe'
        else:
            return 'csv'
    else:
        return 'csv'

def _parse_csv_rows(text: str):
    """Parse CSV lines into list of lists of strings."""
    lines = text.strip().split('\n')
    rows = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        # Simple split by comma, no escaping of quotes
        fields = line.split(',')
        rows.append(fields)
    return rows

def _parse_pipe_rows(text: str):
    """Parse pipe-delimited lines into list of lists of strings."""
    lines = text.strip().split('\n')
    rows = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        fields = [f.strip() for f in line.split('|')]
        rows.append(fields)
    return rows

def _parse_json_rows(text: str):
    """Parse JSON list of objects into header and data rows."""
    data = json.loads(text)
    if not isinstance(data, list):
        raise ValueError("JSON input must be a list of objects")
    if not data:
        raise ValueError("JSON list is empty")
    headers = list(data[0].keys())
    rows = []
    for item in data:
        row = [str(item.get(h, '')) for h in headers]
        rows.append(row)
    return headers, rows

def _is_numeric(val: str) -> bool:
    """Check if a string can be interpreted as a number (int or float)."""
    if val == '' or val is None:
        return False
    try:
        float(val)
        return True
    except ValueError:
        return False

def _escape_html(val: str) -> str:
    """Escape HTML special characters."""
    return val.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')

def _escape_markdown(val: str) -> str:
    """Escape pipe characters in Markdown table cells."""
    return val.replace('|', '\\|')

def convert(text: str) -> str:
    """
    Convert delimited text to Markdown and HTML tables.

    Args:
        text: Input string in CSV, JSON (list of objects), or pipe-delimited format.

    Returns:
        Combined string: Markdown table, blank line, HTML table, and optional mismatch report.
    """
    fmt = _detect_format(text)
    headers = []
    rows = []
    mismatches = []

    if fmt == 'json':
        headers, rows = _parse_json_rows(text)
        expected_len = len(headers)
        for idx, row in enumerate(rows):
            if len(row) != expected_len:
                mismatches.append((idx + 1, len(row), expected_len))
    elif fmt == 'pipe':
        all_rows = _parse_pipe_rows(text)
        if not all_rows:
            raise ValueError("No data rows")
        headers = all_rows[0]
        expected_len = len(headers)
        for idx, row in enumerate(all_rows[1:], start=2):
            if len(row) != expected_len:
                mismatches.append((idx, len(row), expected_len))
            rows.append(row)
    else:  # csv
        all_rows = _parse_csv_rows(text)
        if not all_rows:
            raise ValueError("No data rows")
        headers = all_rows[0]
        expected_len = len(headers)
        for idx, row in enumerate(all_rows[1:], start=2):
            if len(row) != expected_len:
                mismatches.append((idx, len(row), expected_len))
            rows.append(row)

    # Determine numeric columns
    num_cols = len(headers)
    numeric_cols = [False] * num_cols
    for col_idx in range(num_cols):
        values = [row[col_idx] for row in rows if col_idx < len(row)]
        non_empty = [v for v in values if v.strip() != '']
        if non_empty and all(_is_numeric(v) for v in non_empty):
            numeric_cols[col_idx] = True

    # Build Markdown table
    md_lines = []
    # Header row
    escaped_headers = [_escape_markdown(h) for h in headers]
    md_lines.append('| ' + ' | '.join(escaped_headers) + ' |')
    # Alignment row
    align = []
    for col_idx in range(num_cols):
        if numeric_cols[col_idx]:
            align.append('---:')
        else:
            align.append(':---')
    md_lines.append('| ' + ' | '.join(align) + ' |')
    # Data rows
    for row in rows:
        cells = []
        for col_idx in range(num_cols):
            if col_idx < len(row):
                val = _escape_markdown(row[col_idx])
            else:
                val = ''
            cells.append(val)
        md_lines.append('| ' + ' | '.join(cells) + ' |')
    md_table = '\n'.join(md_lines)

    # Build HTML table
    html_lines = []
    html_lines.append('<table>')
    html_lines.append('  <thead>')
    html_lines.append('    <tr>')
    for h in headers:
        html_lines.append(f'      <th>{_escape_html(h)}</th>')
    html_lines.append('    </tr>')
    html_lines.append('  </thead>')
    html_lines.append('  <tbody>')
    for row in rows:
        html_lines.append('    <tr>')
        for col_idx in range(num_cols):
            if col_idx < len(row):
                val = _escape_html(row[col_idx])
            else:
                val = ''
            if numeric_cols[col_idx]:
                html_lines.append(f'      <td style="text-align:right">{val}</td>')
            else:
                html_lines.append(f'      <td>{val}</td>')
        html_lines.append('    </tr>')
    html_lines.append('  </tbody>')
    html_lines.append('</table>')
    html_table = '\n'.join(html_lines)

    # Build mismatch report
    mismatch_report = ''
    if mismatches:
        lines = []
        for row_num, got, expected in mismatches:
            lines.append(f"Row {row_num} has {got} fields, expected {expected}")
        mismatch_report = '\n'.join(lines)

    # Combine output
    parts = [md_table, '', html_table]
    if mismatch_report:
        parts.append('')
        parts.append(mismatch_report)
    return '\n'.join(parts)
